import zipfile
import re
from xml.etree import ElementTree as ET

NS = {
    'main': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'rel': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
    'pkgrel': 'http://schemas.openxmlformats.org/package/2006/relationships',
}

path = 'budget.xlsx'
z = zipfile.ZipFile(path)
print("Files in archive:", z.namelist())

wb_xml = ET.fromstring(z.read('xl/workbook.xml'))
rels_xml = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))

rid_to_target = {}
for rel in rels_xml:
    rid_to_target[rel.get('Id')] = rel.get('Target')

shared_strings = []
if 'xl/sharedStrings.xml' in z.namelist():
    ss_xml = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in ss_xml.findall('main:si', NS):
        text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
        shared_strings.append(text)

def col_to_idx(col_letter):
    idx = 0
    for ch in col_letter:
        idx = idx * 26 + (ord(ch) - ord('A') + 1)
    return idx - 1  # 0-based

def cell_value(c):
    t = c.get('t')
    v = c.find('main:v', NS)
    if v is None:
        return None
    if t == 's':
        return shared_strings[int(v.text)]
    if t == 'b':
        return v.text == '1'
    if t == 'inlineStr':
        return ''.join(x.text or '' for x in c.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
    return v.text

for sheet in wb_xml.findall('.//main:sheet', NS):
    name = sheet.get('name')
    rid = sheet.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
    target = rid_to_target[rid]
    if not target.startswith('xl/'):
        target = 'xl/' + target.lstrip('/')
    print(f"\n=== Sheet: {name} ===")
    sheet_xml = ET.fromstring(z.read(target))
    rows = {}
    for c in sheet_xml.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c'):
        ref = c.get('r')
        m = re.match(r'([A-Z]+)(\d+)', ref)
        col, row = m.group(1), int(m.group(2))
        rows.setdefault(row, {})[col] = cell_value(c)
    max_row = max(rows)
    all_cols = sorted({col for r in rows.values() for col in r}, key=col_to_idx)
    for r in range(1, max_row + 1):
        vals = [rows.get(r, {}).get(col, '') for col in all_cols]
        print(f"Row {r}: {vals}")

