import zipfile
import re
from xml.etree import ElementTree as ET

NS = {'main': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
z = zipfile.ZipFile('budget.xlsx')
sheet_xml = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

def cell_value(c):
    t = c.get('t')
    if t == 'inlineStr':
        return ''.join(x.text or '' for x in c.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
    v = c.find('main:v', NS)
    return v.text if v is not None else None

rows = {}
for c in sheet_xml.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c'):
    m = re.match(r'([A-Z]+)(\d+)', c.get('r'))
    col, row = m.group(1), int(m.group(2))
    rows.setdefault(row, {})[col] = cell_value(c)

expenses = []
for r in range(11, 23):
    cat = rows[r]['A']
    sub = rows[r]['B']
    amt = float(rows[r]['C'])
    expenses.append((cat, sub, amt))
    print(f"{cat:15s} | {sub:15s} | {amt}")

total = sum(e[2] for e in expenses)
print(f"\nTotal expenses (rows 11-22): {total}")

by_cat = {}
for cat, sub, amt in expenses:
    by_cat[cat] = by_cat.get(cat, 0) + amt
for cat, amt in by_cat.items():
    print(f"  {cat}: {amt}")
print(f"\nSum of category subtotals: {sum(by_cat.values())}")

